reactions.evaluate:
function (triggerType, triggerData, reactorToken, item, activationName, api) {
    var firstAttack = api.getTokenFlags(reactorToken, "firstAttack")
    var firstTechAttack = api.getTokenFlags(reactorToken, "firstTechAttack");
    const isCurrentTurn = game.combat?.combatant?.tokenId === reactorToken.id;
    const isInDangerZone = api.inDangerZone(reactorToken);
    if (firstAttack == undefined) {
        var firstAttack = true
    }
    if (firstTechAttack == undefined) {
        var firstTechAttack = true
    }
	var firstAttack = firstAttack && firstTechAttack

    if (firstAttack && isCurrentTurn && isInDangerZone) {
        return true;
    };
    if (triggerType == "onTurnStart") {
        return true;
    };
    return false;
}

reactions.activationCode:
async function (triggerType, triggerData, reactorToken, item, activationName, api) {
    if (triggerType == "onTurnStart") {
        await api.addTokenFlags(reactorToken, { firstAttack: true });
        await api.addTokenFlags(reactorToken, { firstTechAttack: true });
    };
    if (triggerType == "onAttack" || triggerType == "onTechAttack") {
        if (triggerType == "onAttack") {
           await api.addTokenFlags(reactorToken, { firstAttack: false });
        };
        if (triggerType == "onTechAttack") {
           await api.addTokenFlags(reactorToken, { firstTechAttack: false });
        };
        await api.addGlobalBonus(reactorToken.actor, {
        	name: "Aggressive Heat Bleed",
            type: "damage",
            uses: 1,
            damageMode: "add",
            damage: [
            {
                val: "2",
                type: "Heat"
            }
        	],
        	consumeOnUsage: true
    		}, {
            duration: "indefinite",
            durationTurns: 1,
            origin: reactorToken.id,
            consumption: {
                trigger: [
                    "onMiss",
                    "onPreDamage",
                    "onTurnEnd"
                ],
                originId: reactorToken.id,
                role: "source"
            }
        });
    }
}

